PRAGMA foreign_keys = ON;
CREATE TABLE users(id TEXT PRIMARY KEY, mobile TEXT NOT NULL UNIQUE, name TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE otp_challenges(id TEXT PRIMARY KEY, mobile TEXT NOT NULL, code_hash TEXT NOT NULL, expires_at TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0 CHECK(attempts>=0), consumed_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, request_ip TEXT);
CREATE INDEX idx_otp_mobile_created ON otp_challenges(mobile, created_at);
CREATE TABLE roles(id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE permissions(id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE);
CREATE TABLE user_roles(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, role_id TEXT NOT NULL REFERENCES roles(id) ON DELETE CASCADE, PRIMARY KEY(user_id,role_id));
CREATE TABLE categories(id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)));
CREATE TABLE products(id TEXT PRIMARY KEY, category_id TEXT REFERENCES categories(id) ON DELETE SET NULL, slug TEXT NOT NULL UNIQUE, sku TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT, price_irt INTEGER NOT NULL CHECK(price_irt>=0), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), seo_title TEXT, seo_description TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE product_images(id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, path TEXT NOT NULL, alt_text TEXT, sort_order INTEGER NOT NULL DEFAULT 0, is_primary INTEGER NOT NULL DEFAULT 0 CHECK(is_primary IN(0,1)));
CREATE TABLE inventory(product_id TEXT PRIMARY KEY REFERENCES products(id) ON DELETE CASCADE, quantity INTEGER NOT NULL DEFAULT 0 CHECK(quantity>=0), updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE addresses(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT, recipient_name TEXT NOT NULL, mobile TEXT NOT NULL, province TEXT NOT NULL, city TEXT NOT NULL, address TEXT NOT NULL, postal_code TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE carts(id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE cart_items(cart_id TEXT NOT NULL REFERENCES carts(id) ON DELETE CASCADE, product_id TEXT NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL CHECK(quantity>0), PRIMARY KEY(cart_id,product_id));
CREATE TABLE orders(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), address_id TEXT REFERENCES addresses(id), status TEXT NOT NULL CHECK(status IN('PENDING','PAID','PROCESSING','SHIPPED','DELIVERED','CANCELLED','FAILED')), subtotal_irt INTEGER NOT NULL CHECK(subtotal_irt>=0), shipping_irt INTEGER NOT NULL CHECK(shipping_irt>=0), total_irt INTEGER NOT NULL CHECK(total_irt>=0), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE order_items(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id TEXT NOT NULL REFERENCES products(id), sku TEXT NOT NULL, name TEXT NOT NULL, unit_price_irt INTEGER NOT NULL CHECK(unit_price_irt>=0), quantity INTEGER NOT NULL CHECK(quantity>0), line_total_irt INTEGER NOT NULL CHECK(line_total_irt>=0));
CREATE TABLE payments(id TEXT PRIMARY KEY, order_id TEXT NOT NULL UNIQUE REFERENCES orders(id) ON DELETE CASCADE, status TEXT NOT NULL CHECK(status IN('CREATED','REDIRECTED','CALLBACK','VERIFYING','PAID','FAILED','CANCELLED','UNKNOWN')), amount_irt INTEGER NOT NULL CHECK(amount_irt>=0), authority TEXT UNIQUE, ref_id TEXT, paid_at TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payment_attempts(id TEXT PRIMARY KEY, payment_id TEXT NOT NULL REFERENCES payments(id) ON DELETE CASCADE, authority TEXT, request_code INTEGER, verify_code INTEGER, callback_status TEXT, raw_status TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE favorites(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,product_id));
CREATE TABLE reviews(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), product_id TEXT NOT NULL REFERENCES products(id), rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5), body TEXT NOT NULL, approved INTEGER NOT NULL DEFAULT 0 CHECK(approved IN(0,1)), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE coupons(id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, kind TEXT NOT NULL CHECK(kind IN('PERCENT','FIXED')), value INTEGER NOT NULL CHECK(value>=0), max_uses INTEGER, active INTEGER NOT NULL DEFAULT 1 CHECK(active IN(0,1)), expires_at TEXT);
CREATE TABLE coupon_usages(coupon_id TEXT NOT NULL REFERENCES coupons(id), user_id TEXT NOT NULL REFERENCES users(id), order_id TEXT NOT NULL UNIQUE REFERENCES orders(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(coupon_id,user_id));
CREATE TABLE audit_logs(id TEXT PRIMARY KEY, actor_user_id TEXT REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT, entity_id TEXT, metadata_json TEXT, ip TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_products_category ON products(category_id,active);
CREATE INDEX idx_orders_user ON orders(user_id,created_at DESC);
CREATE INDEX idx_payments_authority ON payments(authority);
CREATE INDEX idx_audit_created ON audit_logs(created_at DESC);
